from rdkit import Chem
import numpy as np
m=Chem.MolFromMolFile('ligand.mol',removeHs=False);r=np.loadtxt('optimized.xyz',skiprows=2,usecols=(1,2,3))
changes=[]
for b in m.GetBonds():
 i,j=b.GetBeginAtomIdx(),b.GetEndAtomIdx();d=np.linalg.norm(r[i]-r[j]);
 if (m.GetAtomWithIdx(i).GetSymbol()=='H' or m.GetAtomWithIdx(j).GetSymbol()=='H') and not .9<d<1.3:changes.append((i,j,d))
 elif (m.GetAtomWithIdx(i).GetSymbol()=='P' or m.GetAtomWithIdx(j).GetSymbol()=='P') and not 1.6<d<2:changes.append((i,j,d))
print('unusual ligand bonds',changes)
